"""Literal independently authored provider-shaped observations; never exchange data."""
import hashlib
import json

# CRC values generated by independent bitwise reference rather than adapter code.
def _crc(text):
    value=0xffffffff
    for byte in text.encode():
        value^=byte
        for _ in range(8):value=(value>>1)^(0xedb88320 if value&1 else 0)
    return value^0xffffffff

def _book(kind,bids,asks,checksum_text):
    return json.dumps({'channel':'book','type':kind,'data':[{'symbol':'BTC/USD',
        'bids':[{'price':p,'qty':q} for p,q in bids],
        'asks':[{'price':p,'qty':q} for p,q in asks],
        'checksum':_crc(checksum_text)}]},separators=(',',':'))

EVENTS=(
    _book('snapshot',[('100.00','2.00000000')],[('101.00','3.00000000')],'1010030000000010000200000000'),
    _book('update',[('100.00','4.00000000')],[],'1010030000000010000400000000'),
    json.dumps({'channel':'trade','type':'update','data':[{'symbol':'BTC/USD','side':'buy','trade_id':7,'price':'101.00','qty':'0.25000000','timestamp':'2026-01-01T00:00:00.000000001Z'}]},separators=(',',':')),
    _book('update',[('100.00','0.00000000')],[],'10100300000000'),
    _book('snapshot',[('99.00','1.00000000')],[('102.00','2.00000000')],'102002000000009900100000000'),
)
SHA256=hashlib.sha256(('\n'.join(EVENTS)+'\n').encode()).hexdigest()
